1|/* ---------- Hero art: rain (Off / Drizzle / Moderate / Storm) ----------
2|   Boxless: the cloud IS the button. Halos are open (rays, glow), never a ring
3|   or a frame, so nothing reads as a container. Nothing loops: drops and the
4|   bolt only move on hover (.rb:hover) and when a new state is drawn. */
5|const CLOUD='M30 64C18 64 14 53 21 47C19 36 31 29 40 34C44 22 62 20 68 32C80 30 89 41 84 50C90 56 86 64 77 64Z';
6|const CLOUD_IN='M33 58C27 57 26 51 30 48M47 33C51 27 59 27 62 33M70 40C76 40 80 45 79 50';
7|const DROPS=[[],[[40,73],[54,77],[66,72]],[[32,72],[43,80],[53,72],[63,80],[73,72],[48,90],[68,90]],[[30,72],[40,82],[70,82],[78,72],[34,92],[76,92]]];
8|const BOLT='M57 62L47 79H55L49 95L66 74H57.5L63 62Z';
9|const HALO=['none','#58AEFF','#F2B705','#E5484D'];
10|const drops=(s,attr)=>DROPS[s].map(([x,y],i)=>`<path class="drop" style="--i:${i}" d="M${x} ${y}l-2.2 ${s===1?5:7}" ${attr}/>`).join('');
11|const rays=(n,r1,r2,jit=0)=>Array.from({length:n},(_,i)=>{const a=i/n*Math.PI*2+.07,j=jit?((i*37)%7-3)*jit:0,b=r1+(i%2?0:-2),e=r2+(i%2?-3:0)+j;return `M${(50+b*Math.cos(a)).toFixed(1)} ${(50+b*Math.sin(a)).toFixed(1)}L${(50+e*Math.cos(a)).toFixed(1)} ${(50+e*Math.sin(a)).toFixed(1)}`}).join('');
12|const RAIN = {
13|  engraving(s){
14|    const halo = s? `<path class="halo etch" pathLength="1" d="${rays(32,40,48)}" fill="none" style="stroke:${HALO[s]}" stroke-width="${s===3?2:1.6}" stroke-linecap="square"/>`:'';
15|    const fill = ['none','url(#hatch)','url(#hatch2)','url(#hatch2)'][s];
16|    const body = `<path ${s?'class="etch" pathLength="1"':''} d="${CLOUD}" fill="${fill}" stroke="#2A241C" stroke-width="${s?1.6:1.1}" ${s?'':'stroke-dasharray="2 2.2" opacity=".5"'}/>`
17|      + (s===3?`<path d="${CLOUD}" fill="#2A241C" opacity=".38"/>`:'')
18|      + (s?`<path d="${CLOUD_IN}" fill="none" stroke="${s>=2?'#F7F1DE':'#2A241C'}" stroke-width=".8" opacity=".8"/>`:'');
19|    const bolt = s===3?`<g class="bolt"><path d="${BOLT}" fill="#F7F1DE" stroke="#2A241C" stroke-width="1.4" stroke-linejoin="miter"/><path d="${BOLT}" fill="url(#hatch)" opacity=".35"/></g>`:'';
