113|<!--DEFS-->
114|<header>
115|  <h1>Rain, in three <b>looks</b></h1>
116|  <p>No frames, no boxes: the cloud is the button. It moves only when you hover over it or click it, and at rest it stays still. Click the big one to change the weather; the four next to it show every state.</p>
117|  <div class="legend"><span><i style="border:1.5px dashed #999"></i>Off</span><span><i style="background:#58AEFF"></i>Drizzle</span><span><i style="background:#F2B705"></i>Moderate</span><span><i style="background:#E5484D"></i>Storm</span></div>
118|</header>
119|<main id="bands"></main>
120|<footer>Hand-built SVG and CSS. Keyboard: Tab to a cloud, then Enter or Space. With reduced motion turned on, changes simply fade.</footer>
121|<script>
122|function svgWrap(inner, vb='0 0 24 24', cls='ic-svg'){return `<svg class="${cls}" viewBox="${vb}" aria-hidden="true" focusable="false">${inner}</svg>`;}
123|/*RAIN*/
124|const RAIN_NAMES=['Off','Drizzle','Moderate','Storm'];
125|const SK=[
126| ['engraving','Antique engraving','Etched with a burin: cross-hatching darkens the cloud and the halo is a ring of engraved rays.','Change: coin turn and the lines etch in. Hover: burin shimmer and the rain drips once.'],
127| ['watercolor','Watercolor','Soft washes on paper: the cloud deepens from pale blue to slate and the halo is a glow of pigment.','Change: the washes bloom and the edges dry in. Hover: the pigment bleeds and the rain drips once.'],
128| ['ink','Ink doodle','Blue ballpoint on a notebook page: the cloud fills with hatching and the halo is a burst of pen strokes.','Change: the strokes draw themselves and it lands like a stamp. Hover: a wiggle and the rain drips once.']];
129|const st={engraving:1,watercolor:2,ink:3};
130|const pips=(n,on)=>`<span class="pips" aria-hidden="true">${Array.from({length:n},(_,i)=>`<i class="${i===on?'on':''}"></i>`).join('')}</span>`;
131|const face=(k,s)=>`<span class="face">${RAIN[k](s)}</span>`;
132|function live(k){const s=st[k],n=(s+1)%4;return `<button class="rb" id="live-${k}" data-k="${k}" aria-label="Rain: ${RAIN_NAMES[s]}. Click for ${RAIN_NAMES[n]}." style="--size:128px"><span class="art">${face(k,s)}</span>
133|  <span class="cap"><span class="k">Rain</span><span class="v" aria-live="polite">${RAIN_NAMES[s]}</span>${pips(4,s)}</span></button>`;}
134|function band([k,name,desc,motion]){
135|  return `<section class="band" data-skin="${k}" aria-label="${name}">
136|   <div class="who"><h2>${name}</h2><p>${desc}</p><p class="motion">${motion}</p></div>
137|   <div class="live">${live(k)}</div>
138|   <div class="states">${[0,1,2,3].map(s=>`<figure><button class="rb sample ${s===st[k]?'cur':''}" data-k="${k}" data-s="${s}" aria-label="Show ${RAIN_NAMES[s]}"><span class="art">${face(k,s)}</span></button><figcaption><b>${RAIN_NAMES[s]}</b>${['faint, dashed cloud','celeste halo','darker cloud, yellow halo','dark cloud, lightning, red halo'][s]}</figcaption></figure>`).join('')}</div></section>`;}
139|const bands=document.getElementById('bands');
140|bands.innerHTML=SK.map(band).join('');
141|function setState(k,s,focusLive){
142|  st[k]=s;const sec=document.querySelector(`.band[data-skin="${k}"]`);
143|  const old=sec.querySelector('.live .rb');const had=document.activeElement===old;
144|  sec.querySelector('.live').innerHTML=live(k);
145|  sec.querySelectorAll('.sample').forEach(b=>b.classList.toggle('cur',+b.dataset.s===s));
146|  if(had||focusLive) sec.querySelector('.live .rb').focus({preventScroll:true});
147|}
148|bands.addEventListener('click',e=>{const b=e.target.closest('.rb');if(!b)return;const k=b.dataset.k;
149|  if(b.classList.contains('sample')){setState(k,+b.dataset.s,false);const a=b.querySelector('.art');a.innerHTML=face(k,+b.dataset.s);}
150|  else setState(k,(st[k]+1)%4,true);});
151|const q=new URLSearchParams(location.search);if(q.get('s')){SK.forEach(([k])=>setState(k,+q.get('s')));}
152|</script>
153|</body>
