1|// Theme default: light unless the user explicitly stored light/dark.
2|// The inline script in layout.tsx must stay in sync with initialTheme
3|// (it cannot import this module), so keep the "light" fallback there.
4|export type ThemeName = "light" | "dark";
5|
6|export const THEME_KEY = "lectoria.theme";
7|
8|export function initialTheme(stored: unknown): ThemeName {
9|  return stored === "light" || stored === "dark" ? stored : "light";
10|}
11|
12|export const THEME_SCRIPT = `(function(){try{var t=localStorage.getItem(${JSON.stringify(THEME_KEY)});if(t!=="light"&&t!=="dark"){t="light";}document.documentElement.setAttribute("data-theme",t);}catch(e){document.documentElement.setAttribute("data-theme","light");}})();`;

